messages.content:
{
 "what_you_observe": [
  "Tuesday, February 2. Seven pm.",
  "Phil said in the lobby: Morning, folks. I'm late for a thing.",
  "Rita said in the lobby: Ballroom's yours. I'm on the Rialto. One mic, one cable, a chair if her back's bad. I'll handle the rest.",
  "Rita records Alma at the Rialto and puts her recording on the patch.",
  "Larry records Alma on his last charged take. The reel stays with him.",
  "You are now at Rialto.",
  "There is time for one evening visit. The ballroom lights are on and the station line is open."
 ],
 "your_own_memories": [
  {
   "what_you_did": "Larry records Alma on his last charged take. The reel stays with him.",
   "what_you_said": "I say to whoever's still at the table: 'I'm taking the Rialto. You guys cover the ballroom tonight.' I don't wait for an answer. I'm already at the door with the bag over my shoulder.",
   "your_intention": "The Rialto is closing. This is the one window where she says it to someone who isn't in the room. The party is a rehearsal. The lights will be there again tomorrow. Alma at the booth, talking to Pittsburgh, is not coming back. The daughter already asked to hear it once. I'm not going to be the reason it's gone."
  }
 ],
 "who_you_are_with": "your present location",
 "physical_choices": {
  "deliver_reel": "Bring your recording to the station patch for Rita.",
  "screen_party": "Show the festival footage at the ballroom if you have it.",
  "go_home": "Clock off and go home."
 }
}
